/**
 * Bundle monkey main controller.
 */
@FxControllerService
public class MainController extends AbstractFxController implements DomainContextProvider {

  private static final String STYLE_MODIFIED = "bundle-modified";   // css style for modified bundle nodes
  private static final String STYLE_MISSING = "bundle-missing";     // css style for missing translation in bundle nodes

  @Bindable
  private Collection<? extends BundleNode> bundles;       // bundle nodes shown in tree table

  @Bindable
  private String filter;                                  // filter for nodes
  private String lastFilter;                              // last filter setting

  @Bindable
  private String find;                                    // search text for keys and translations
  private String lastFind;                                // last search

  @FXML
  private BorderPane outerBorderPane;                     // outer borderpane with menu, inner borderpane and buttons below

  @FXML
  private BorderPane innerBorderPane;                     // inner border pane with locale selector, tree table and bundle editor

  @FXML
  private MenuItem preferencesItem;

  @FXML
  private MenuItem discardItem;

  @FXML
  private MenuItem exitItem;

  @FXML
  private MenuItem helpItem;

  @FXML
  private MenuItem aboutItem;

  @FXML
  private FxTreeTableView<BundleNode> bundlesTreeTable;

  @FXML
  private FxTextField filterField;

  @FXML
  private FxTextField findField;

  @FXML
  private FxToggleButton ucLcButton;

  @FXML
  private FxLabel modificationLabel;

  @FXML
  private FxButton saveButton;

  @FXML
  private ResourceBundle resources;

  private BundleRepository bundleRepository;                      // the internal bundle model
  private TablePopup<BundleNode> bundleNodeTablePopup;            // popup menu and config
  private LocaleSelector localeSelector;                          // the active locales
  private BundleEditor bundleEditor;                              // the bundle editor controller
  private List<TreeItem<BundleNode>> bundleTreeItems;             // all tree items
  private TreeItem<BundleNode> foundItem;                         // != null if current found item
  private int foundIndex;                                         // index in bundleTreeItems if foundItem != null
  private String foundLocale;                                     // != null if current found translation
  private NavigationServer navigationServer;                      // bundle navigation triggered by client


  @Override
  public DomainContext getDomainContext() {
    return Application.getInstance().getDomainContext();
  }

  @FXML
  public void initialize() {
    bundleRepository = new BundleRepository();

    localeSelector = Fx.load(LocaleSelector.class);
    innerBorderPane.setTop(localeSelector.getView());

    preferencesItem.setGraphic(Fx.createGraphic("preferences"));
    preferencesItem.setOnAction(e -> PreferencesDialog.show(getView()));

    discardItem.setGraphic(Fx.createGraphic("reload"));
    discardItem.setOnAction(e -> loadRepository());

    exitItem.setGraphic(Fx.createGraphic("exit"));
    exitItem.setOnAction(e -> exit());

    helpItem.setGraphic(Fx.createGraphic("help"));
    helpItem.setOnAction(e -> help());

    aboutItem.setGraphic(Fx.createGraphic("about"));
    aboutItem.setOnAction(e -> AboutView.show(getView()));

    bundleEditor = Fx.load(BundleEditor.class);
    innerBorderPane.setRight(bundleEditor.getView());

    bundlesTreeTable.getSelectionModel().getSelectedItems().addListener((ListChangeListener<TreeItem<BundleNode>>) c -> {
      TreeItem<BundleNode> selectedItem = bundlesTreeTable.getSelectionModel().getSelectedItem();
      bundleEditor.setBundleNode(selectedItem == null ? null : selectedItem.getValue());
    });

    filterField.setAutoSelect(true);
    filterField.setOnAction(e -> {
      if (runFilter()) {
        Platform.runLater(bundlesTreeTable::requestFocus);
      }
      else {
        Platform.runLater(filterField::requestFocus);
      }
    });
    filterField.setTooltip(new Tooltip(resources.getString("filter=F2, clear=Shift-F2")));

    findField.setAutoSelect(true);
    findField.setOnAction(e -> {
      if (!runFind(null)) {
        Platform.runLater(findField::requestFocus);
      }
    });
    findField.setTooltip(new Tooltip(resources.getString("next=F3, previous=Shift-F3")));

    ucLcButton.setBindable(false);
    ucLcButton.setOnAction(event -> lastFilter = null);
    ucLcButton.setGraphic(Fx.createGraphic("uclc"));
    ucLcButton.setTooltip(new Tooltip(resources.getString("toggle case sensitivity")));

    saveButton.setOnAction(e -> save());
    saveButton.setGraphic(Fx.createGraphic("save"));

    navigationServer = new NavigationServer(this::navigateViaHierarchyDump);
  }

  @Override
  public void configure() {
    preferencesItem.setDisable(!SecurityFactory.getInstance().getSecurityManager().evaluate(
      getDomainContext(), SecurityFactory.getInstance().getExecutePermission(), PreferencesDialog.class).isAccepted());

    bundlesTreeTable.setSortable(false);
    bundlesTreeTable.setReorderable(false);
    bundlesTreeTable.setRowFactory(treeTableView -> new TreeTableRow<>() {
      @Override
      protected void updateItem(BundleNode item, boolean empty) {
        super.updateItem(item, empty);
        if (item != null) {
          if (item.getMissingCount() != 0) {   // missing has priority over modified
            if (!getStyleClass().contains(STYLE_MISSING)) {
              getStyleClass().add(STYLE_MISSING);
            }
            getStyleClass().remove(STYLE_MODIFIED);
          }
          else {
            getStyleClass().remove(STYLE_MISSING);
            if (item.getModificationCount() != 0) {
              if (!getStyleClass().contains(STYLE_MODIFIED)) {
                getStyleClass().add(STYLE_MODIFIED);
              }
            }
            else {
              getStyleClass().remove(STYLE_MODIFIED);
            }
          }
        }
        else {
          getStyleClass().removeAll(STYLE_MODIFIED, STYLE_MISSING);
        }
      }
    });

    // register F-keys
    getView().addEventFilter(KeyEvent.ANY, e -> {
      if (!e.isAltDown() && !e.isControlDown() && !e.isMetaDown() && !e.isShortcutDown()) {
        if (e.getCode() == KeyCode.F3) {
          if (e.getEventType() == KeyEvent.KEY_PRESSED) {
            findField.updateModel();
            if (!runFind(!e.isShiftDown())) {
              Platform.runLater(findField::requestFocus);
            }
            e.consume();
          }
        }
        else if (e.getCode() == KeyCode.F2) {
          if (e.getEventType() == KeyEvent.KEY_PRESSED) {
            if (e.isShiftDown()) {
              // clear filter
              filter = null;
              filterField.updateView();
            }
            else {
              filterField.updateModel();
            }
            if (runFilter()) {
              Platform.runLater(bundlesTreeTable::requestFocus);
            }
            else {
              Platform.runLater(filterField::requestFocus);
            }
            e.consume();
          }
        }
      }
    });

    bundleNodeTablePopup = Rdc.createTablePopup(bundlesTreeTable, "bundlesTreeTable", resources.getString("Bundles"));
    bundleNodeTablePopup.setColumnMenuEnabled(false);
    bundleNodeTablePopup.loadPreferences();
    bundleRepository.addBundlesUpdatedListener(this::bundlesUpdated);
    loadRepository();
    localeSelector.setRepository(bundleRepository);

    configureContextMenu();
  }

  /**
   * Asks the user whether to exit the application and does so if yes.
   */
  public void exit() {
    Fx.yes(getView(), bundleRepository.getModificationCount() != 0 ?
           resources.getString("ExitModifiedAction") :
           resources.getString("ExitAction"),
           false, () -> {
          if (navigationServer != null) {
            navigationServer.shutdown();
          }
          Fx.terminate();
        });
  }


  /**
   * Configures the context menu of the tree table.
   */
  private void configureContextMenu() {
    ContextMenu contextMenu = bundlesTreeTable.getContextMenu();
    MenuItem renameBundleItem = Fx.create(MenuItem.class);
    renameBundleItem.setText(resources.getString("rename bundle"));
    renameBundleItem.setOnAction(e -> renameBundle());
    contextMenu.getItems().add(0, renameBundleItem);
    MenuItem renamePackageItem = Fx.create(MenuItem.class);
    renamePackageItem.setText(resources.getString("rename package"));
    renamePackageItem.setOnAction(e -> renamePackage());
    contextMenu.getItems().add(0, renamePackageItem);
    contextMenu.addEventHandler(WindowEvent.WINDOW_SHOWING, event -> {
      TreeItem<BundleNode> selectedItem = bundlesTreeTable.getSelectionModel().getSelectedItem();
      boolean disable = selectedItem == null || bundleRepository.getModificationCount() != 0;
      renameBundleItem.setDisable(disable);
      renamePackageItem.setDisable(disable);
    });
  }

  /**
   * Applies the filter to the shown tree items.
   *
   * @return true if filter applied, else all shown
   */
  private boolean runFilter() {
    boolean filtered = false;
    if (!Objects.equals(filter, lastFilter)) {
      lastFilter = filter;
      if (!StringHelper.isAllWhitespace(filter)) {
        boolean ucLcSensitive = ucLcButton.isSelected();
        String lcFilter = ucLcSensitive ? filter : filter.toUpperCase(Locale.ROOT);
        boolean not = false;
        if (lcFilter.startsWith("!") || lcFilter.startsWith("-")) {
          not = true;
          lcFilter = lcFilter.substring(1);
        }
        List<BundleNode> foundNodes = new ArrayList<>();
        for (BundleNode bundleNode : bundleRepository.getBundles()) {
          String name = ucLcSensitive ? bundleNode.getName() : bundleNode.getName().toUpperCase(Locale.ROOT);
          if (name.contains(lcFilter) ^ not) {
            foundNodes.add(bundleNode);
          }
        }
        bundles = foundNodes;
        filtered = true;
      }
      else {
        bundles = bundleRepository.getBundles();
      }
      bundleTreeItems = null;
      bundlesTreeTable.updateView();
    }
    return filtered;
  }

  /**
   * Finds the next/previous key or translation.
   *
   * @param next true if start search at next item, false if search backwards starting at previous item, null if find next starting at current item
   * @return true if found
   */
  private boolean runFind(Boolean next) {
    if (!Objects.equals(find, lastFind)) {
      foundItem = null;
      foundIndex = -1;
      foundLocale = null;
    }
    boolean found = false;
    lastFind = find;
    if (!StringHelper.isAllWhitespace(find)) {
      if (bundleTreeItems == null) {
        bundleTreeItems = bundlesTreeTable.getTreeItems();
        foundItem = null;
        foundLocale = null;
      }
      if (bundleTreeItems.size() > 1) {
        if (foundItem == null) {
          // take selected item as starting point
          foundItem = bundlesTreeTable.getSelectionModel().getSelectedItem();
        }
        if (foundItem == null) {
          // no selected item: start from beginning
          foundItem = bundleTreeItems.get(0);
          foundIndex = 0;
        }
        else {
          foundIndex = bundleTreeItems.indexOf(foundItem);
        }
        found = runFind(foundItem, foundIndex, foundLocale, next);
      }
    }
    return found;
  }

  /**
   * Finds the next/previous key or translation.
   *
   * @param item the current item to start
   * @param itemNdx the index of the item in bundleTreeItems
   * @param locale != null if check translations first
   * @param next true if start search at next item, false if search backwards starting at previous item, null if find next starting at current item
   * @return true if found
   */
  private boolean runFind(TreeItem<BundleNode> item, int itemNdx, String locale, Boolean next) {
    String ucFind = ucLcButton.isSelected() ? find : find.toUpperCase(Locale.ROOT);
    if (item.isLeaf()) {
      List<String> locales = new ArrayList<>(bundleRepository.getLocales());
      if (checkTranslations(item, ucFind, locale == null ? -1 : locales.indexOf(locale), next)) {
        foundIndex = itemNdx;
        showFoundItem();
        return true;
      }
    }

    // nothing more found in translations
    foundLocale = null;

    Holder<TreeItem<BundleNode>> itemHolder = new Holder<>();
    itemHolder.accept(item);
    int startNdx = itemNdx;
    if (next != null) {
      if (next) {
        startNdx = toNextItem(itemNdx, itemHolder);
      }
      else {
        startNdx = toPreviousItem(itemNdx, itemHolder);
      }
    }

    itemNdx = startNdx;
    do {
      item = itemHolder.get();
      String name = item.getValue().getName();
      if (!ucLcButton.isSelected()) {
        name = name.toUpperCase(Locale.ROOT);
      }
      if (name.contains(ucFind)) {
        foundIndex = itemNdx;
        foundItem = item;
        foundLocale = null;
        showFoundItem();
        return true;
      }
      if (item.isLeaf() && checkTranslations(item, ucFind,-1, next)) {
        foundIndex = itemNdx;
        showFoundItem();
        return true;
      }
      if (Boolean.FALSE.equals(next)) {
        itemNdx = toPreviousItem(itemNdx, itemHolder);
      }
      else {
        itemNdx = toNextItem(itemNdx, itemHolder);
      }
    } while (itemNdx != startNdx);

    return false;
  }

  /**
   * Checks the translations within a {@link BundleKey} tree item.
   *
   * @param item the tree item
   * @param ucFind the uppercase string to search for
   * @param localeNdx the current locale index to continue with, -1 if begin/end of all locales
   * @param next next true if start search at next item, false if search backwards starting at previous item, null if find next starting at current item
   * @return true if found
   */
  private boolean checkTranslations(TreeItem<BundleNode> item, String ucFind, int localeNdx, Boolean next) {
    BundleKey bundleKey = (BundleKey) item.getValue();
    List<String> locales = new ArrayList<>(bundleRepository.getLocales());
    String locale;
    if (Boolean.FALSE.equals(next)) {
      if (localeNdx == -1) {
        localeNdx = locales.size() - 1;
      }
      else {
        localeNdx--;
      }
      while (localeNdx >= 0) {
        locale = locales.get(localeNdx);
        if (checkTranslation(bundleKey, locale, ucFind)) {
          foundItem = item;
          return true;
        }
        --localeNdx;
      }
    }
    else {
      if (localeNdx == -1) {
        localeNdx = 0;
      }
      else {
        localeNdx++;
      }
      while (localeNdx < locales.size()) {
        locale = locales.get(localeNdx);
        if (checkTranslation(bundleKey, locale, ucFind)) {
          foundItem = item;
          return true;
        }
        ++localeNdx;
      }
    }
    return false;
  }

  /**
   * Checks the translation for a locale within a {@link BundleKey} item.
   *
   * @param bundleKey the bundle key
   * @param locale the locale
   * @param ucFind the uppercase string to search for
   * @return true if found
   */
  private boolean checkTranslation(BundleKey bundleKey, String locale, String ucFind) {
    BundleTranslation translation = bundleKey.getTranslation(locale);
    if (translation != null) {
      String value = translation.getValue();
      if (!ucLcButton.isSelected()) {
        value = value.toUpperCase(Locale.ROOT);
      }
      if (value.contains(ucFind)) {
        foundLocale = locale;
        return true;
      }
    }
    return false;
  }

  /**
   * Moves the current item to the next within the item tree.
   *
   * @param itemNdx the index of all tree items
   * @param itemHolder the holder of the current/next tree item
   * @return the new item index
   */
  private int toNextItem(int itemNdx, Holder<TreeItem<BundleNode>> itemHolder) {
    if (itemNdx < bundleTreeItems.size() - 1) {
      itemNdx++;
    }
    else {
      itemNdx = 0;    // wrap
    }
    itemHolder.accept(bundleTreeItems.get(itemNdx));
    return itemNdx;
  }

  /**
   * Moves the current item to the previous within the item tree.
   *
   * @param itemNdx the index of all tree items
   * @param itemHolder the holder of the current/previous tree item
   * @return the new item index
   */
  private int toPreviousItem(int itemNdx, Holder<TreeItem<BundleNode>> itemHolder) {
    if (itemNdx > 0) {
      itemNdx--;
    }
    else {
      itemNdx = bundleTreeItems.size() - 1;   // wrap
    }
    itemHolder.accept(bundleTreeItems.get(itemNdx));
    return itemNdx;
  }

  /**
   * Shows the currently found item.
   */
  private void showFoundItem() {
    // make sure item is visible
    TreeItem<BundleNode> item = foundItem;
    do {
      if (!item.isExpanded()) {
        item.setExpanded(true);
      }
      item = item.getParent();
    } while (item != null);
    int row = bundlesTreeTable.getRow(foundItem);
    if (row >= 0) {
      bundlesTreeTable.scrollToCentered(row);
      bundlesTreeTable.getSelectionModel().select(foundItem);
      if (foundLocale == null) {
        bundlesTreeTable.requestFocus();
        bundleEditor.setBundleNode(foundItem.getValue());
      }
      else {
        bundleEditor.setBundleNode(foundItem.getValue());
        bundleEditor.selectLocale(foundLocale);
      }
    }
  }

  /**
   * Saves all changes to the database.
   */
  private void save() {
    bundleRepository.persist();
    loadRepository();
  }

  /**
   * Renames the selected bundle.
   */
  private void renameBundle() {
    BundleName bundleName = getSelectedBundleName();
    if (bundleName != null) {
      RenameBundleDialog.show(getView(), bundleName, this::loadRepository);
    }
  }

  /**
   * Renames the package of the selected bundle.
   */
  private void renamePackage() {
    BundleName bundleName = getSelectedBundleName();
    if (bundleName != null) {
      RenamePackageDialog.show(getView(), ReflectionHelper.getPackageName(bundleName.getName()),
                               bundleRepository, this::loadRepository);
    }
  }

  /**
   * Gets the currently selected bundle.
   *
   * @return the bundle, null if nothing selected
   */
  private BundleName getSelectedBundleName() {
    BundleName bundleName = null;
    TreeItem<BundleNode> selectedItem = bundlesTreeTable.getSelectionModel().getSelectedItem();
    if (selectedItem != null) {
      BundleNode node = selectedItem.getValue();
      if (node instanceof BundleKey) {
        bundleName = ((BundleKey) node).getBundleName();
      }
      else if (node instanceof BundleName){
        bundleName = ((BundleName) node);
      }
    }
    return bundleName;
  }

  /**
   * Loads the model from the bundle repository and updates the view.
   */
  private void loadRepository() {
    bundleRepository.invalidate();
    bundles = bundleRepository.getBundles();
    bundlesTreeTable.updateView();
    bundlesUpdated(0, true);
    filter = null;
    bundleTreeItems = null;
    filterField.updateView();
  }

  /**
   * Updates the number of modified translations.
   *
   * @param modificationCount the new overall modification count
   */
  private void bundlesUpdated(int modificationCount, boolean reloaded) {
    saveButton.setDisable(modificationCount == 0);
    discardItem.setDisable(modificationCount == 0);
    bundleEditor.setLocales(bundleRepository.getLocales(), bundleRepository.getActiveLocales());
    modificationLabel.setText(CommonBundle.createComment(modificationCount, bundleRepository.getMissingCount(), 0));
    if (reloaded) {
      bundles = bundleRepository.getBundles();
      bundlesTreeTable.updateView();
    }
    else {
      bundlesTreeTable.refresh();
    }
  }

  /**
   * Shows the help browser.
   */
  private void help() {
    String helpUrl = BundleMonkeyPreferences.getInstance().getHelpUrl();
    if (StringHelper.isAllWhitespace(helpUrl)) {
      Fx.info(getView(), "Help URL not configured. Please edit the Preferences!");
    }
    else {
      // extra thread because Desktop blocks FX thread
      new Thread(() -> {
        try {
          Desktop.getDesktop().browse(URI.create(helpUrl));
        }
        catch (IOException ex) {
          throw new TentackleRuntimeException("could not open online help", ex);
        }
      }).start();
    }
  }

  private void navigateViaHierarchyDump(String hierarchyDump) {
    Platform.runLater(() -> {
      Holder<String> localeStr = new Holder<>();
      Holder<String> textValue = new Holder<>();
      Holder<String> bundleName = new Holder<>();
      int ndx1 = hierarchyDump.indexOf(BundleMonkeyHelper.LOCALE_PREFIX);
      if (ndx1 >= 0) {
        int ndx2 = hierarchyDump.indexOf(BundleMonkeyHelper.LOCALE_POSTFIX, ndx1);
        if (ndx2 > ndx1) {
          localeStr.accept(hierarchyDump.substring(ndx1 + BundleMonkeyHelper.LOCALE_PREFIX.length(), ndx2));
          int ndx3 = hierarchyDump.indexOf('\n', ndx2);   // skip first line
          if (ndx3 > ndx2) {
            hierarchyDump.substring(ndx3).lines().forEach(line -> {
              if (textValue.get() == null) {
                int ndx4 = line.indexOf("'");
                if (ndx4 >= 0) {
                  int ndx5 = line.indexOf("'", ndx4 + 1);
                  if (ndx5 > ndx4) {
                    textValue.accept(line.substring(ndx4 + 1, ndx5));
                  }
                }
              }
              if (bundleName.get() == null) {
                int ndx4 = line.indexOf(BundleMonkeyHelper.BUNDLENAME_PREFIX);
                if (ndx4 >= 0) {
                  int ndx5 = line.indexOf(BundleMonkeyHelper.BUNDLENAME_POSTFIX, ndx4 + BundleMonkeyHelper.BUNDLENAME_PREFIX.length());
                  if (ndx5 > ndx4) {
                    bundleName.accept(line.substring(ndx4 + BundleMonkeyHelper.BUNDLENAME_PREFIX.length(), ndx5));
                  }
                }
              }
            });
          }
        }
      }

      if (bundleName.get() != null) {
        Platform.runLater(() -> {
          Holder<TreeItem<BundleNode>> foundItem = new Holder<>();
          Holder<String> foundLocale = new Holder<>();
          for (TreeItem<BundleNode> treeItem : bundlesTreeTable.getTreeItems()) {
            if (bundleName.get().equals(treeItem.getValue().getName())) {
              bundlesTreeTable.getSelectionModel().select(treeItem);
              treeItem.setExpanded(true);
              foundItem.accept(treeItem);
              if (textValue.get() != null) {
                // search for explicit translations first
                for (TreeItem<BundleNode> child : treeItem.getChildren()) {
                  BundleKey bundleKey = (BundleKey) child.getValue();
                  for (BundleTranslation translation : bundleKey.getTranslations().values()) {
                    if (!translation.getLocale().isEmpty() &&
                        localeStr.get().startsWith(translation.getLocale()) &&
                        textValue.get().equals(translation.getValue())) {
                      bundlesTreeTable.getSelectionModel().select(child);
                      foundItem.accept(child);
                      foundLocale.accept(translation.getLocale());
                      break;
                    }
                  }
                }
                if (foundLocale.get() == null) {
                  // search for fallback locale
                  for (TreeItem<BundleNode> child : treeItem.getChildren()) {
                    BundleKey bundleKey = (BundleKey) child.getValue();
                    for (BundleTranslation translation : bundleKey.getTranslations().values()) {
                      if (translation.getLocale().isEmpty() && textValue.get().equals(translation.getValue())) {
                        bundlesTreeTable.getSelectionModel().select(child);
                        foundItem.accept(child);
                        foundLocale.accept(translation.getLocale());
                        break;
                      }
                    }
                  }
                }
              }
              if (foundItem.get() != null) {
                Platform.runLater(() -> {
                  bundlesTreeTable.scrollToCentered(bundlesTreeTable.getSelectionModel().getSelectedIndex());
                  bundleEditor.setBundleNode(foundItem.get().getValue());
                  if (foundLocale.get() != null) {
                    Platform.runLater(() -> bundleEditor.selectLocale(foundLocale.get()));
                  }
                });
              }
              break;
            }
          }
        });
      }
    });
  }

}
